/**
 * @file Recipe Types — Schema-Driven
 * @layer recipes
 * @package @devpulse/coldlight
 *
 * Surface props and recipe definition for ColdLight styling.
 * Zod schemas provide runtime validation at system boundaries
 * (VPB load, API payloads, saved layouts). TypeScript types
 * inferred from schemas — single source of truth.
 *
 * Token types are auto-generated by SD5 pipeline (pnpm ds:tokens:build).
 * Schemas in tokens/schema.ts validate each enum independently.
 * DsSurfacePropsSchema composes them into the recipe input contract.
 */

import { z } from "zod";
import {
	AccentSchema,
	BevelSchema,
	DepthSchema,
	GlassVariantSchema,
	GlowSchema,
	RadiusSchema,
	SizeSchema,
	SurfaceSchema,
} from "$lib/design/tokens/schema.js";

// =============================================================================
// DsSurfaceProps — Zod schema + inferred type
// =============================================================================

/**
 * Zod schema for DsSurfaceProps.
 * Composes token schemas from the SD5 pipeline.
 * Use at boundaries: VPB load, recipe resolution, API payloads.
 */
export const DsSurfacePropsSchema = z.object({
	accent: AccentSchema,
	surface: SurfaceSchema,
	variant: GlassVariantSchema.optional(),
	size: SizeSchema,
	radius: RadiusSchema,
	depth: DepthSchema,
	glow: GlowSchema,
	bevel: BevelSchema,
});

/** Surface props that recipes consume to compute per-slot classes. */
export type DsSurfaceProps = z.infer<typeof DsSurfacePropsSchema>;

// =============================================================================
// RecipeDefinition — Zod schema + inferred type
// =============================================================================

/**
 * Zod schema for recipe registration.
 * Validates id format (kind.surface.variant), kind, label,
 * defaults (partial DsSurfaceProps), and classes function.
 */
export const RecipeDefinitionSchema = z.object({
	id: z.string().regex(/^[a-z][\w-]*\.[a-z][\w-]*\.[a-z][\w-]*$/, {
		message: "Recipe ID must be dot-separated: kind.surface.variant",
	}),
	kind: z.string().min(1),
	label: z.string().min(1),
	defaults: DsSurfacePropsSchema.partial(),
	classes: z.custom<(props: DsSurfaceProps) => Record<string, string>>(
		(val) => typeof val === "function",
		{ message: "classes must be a function (props: DsSurfaceProps) => Record<string, string>" },
	),
});

/** A recipe: props in, per-slot CSS class strings out. */
export type RecipeDefinition = z.infer<typeof RecipeDefinitionSchema>;

// =============================================================================
// RecipeLegend — Per-kind manifest of available recipe variants
// =============================================================================

/** Per-kind manifest of available recipe variants. */
export interface RecipeLegend {
	readonly kind: string;
	readonly defaultId: string;
	readonly ids: readonly string[];
}
